    bag.add((T) "A");
    bag.add((T) "B");
    final Iterator<T> it = bag.iterator();
    it.next();
    it.next();
    assertEquals(3, bag.size());
    it.remove();
    assertEquals(2, bag.size());
    assertThrows(IllegalStateException.class, () -> it.remove());
    assertEquals(2, bag.size());
    it.next();
    it.remove();
