        return;
    }
    final Bag<T> bag = makeObject();
    bag.add((T) "A");
    bag.add((T) "A");
    bag.add((T) "B");
    bag.add((T) "B");
    bag.add((T) "C");
    final Object[] array = bag.toArray();
    int a = 0, b = 0, c = 0;
    for (final Object element : array) {
        a += element.equals("A") ? 1 : 0;
        b += element.equals("B") ? 1 : 0;
        c += element.equals("C") ? 1 : 0;
    }
    assertEquals(2, a);
    assertEquals(2, b);
    assertEquals(1, c);
}

