    bag.add((T) "A");
    bag.add((T) "A");
    bag.add((T) "B");
    bag.add((T) "B");
    bag.add((T) "C");
    bag2.add((T) "A");
    bag2.add((T) "A");
    bag2.add((T) "B");
    bag2.add((T) "B");
    bag2.add((T) "C");
    assertEquals(bag.hashCode(), bag2.hashCode());
    int total = 0;
    total += "A".hashCode() ^ 2;
    total += "B".hashCode() ^ 2;
    total += "C".hashCode() ^ 1;
    assertEquals(total, bag.hashCode());
    assertEquals(total, bag2.hashCode());
}

