/**
 *  Tests that the collection's iterator is fail-fast.
 */
@Test
public void testCollectionIteratorFailFast() {
    if (!isFailFastSupported()) {
        return;
    }
    if (isAddSupported()) {
        resetFull();
        final Iterator<E> iter0 = getCollection().iterator();
        final E o = getOtherElements()[0];
        getCollection().add(o);
        getConfirmed().add(o);
        assertThrows(ConcurrentModificationException.class, () -> iter0.next(), "next after add should raise ConcurrentModification");
        verify();
        resetFull();
        final Iterator<E> iter = getCollection().iterator();
        getCollection().addAll(Arrays.asList(getOtherElements()));
        getConfirmed().addAll(Arrays.asList(getOtherElements()));
        assertThrows(ConcurrentModificationException.class, () -> iter.next(), "next after addAll should raise ConcurrentModification");
        verify();
    }
    if (!isRemoveSupported()) {
        return;
    }
    resetFull();
    try {
        final Iterator<E> iter = getCollection().iterator();
        getCollection().clear();
        iter.next();
        fail("next after clear should raise ConcurrentModification");
    } catch (final ConcurrentModificationException | NoSuchElementException e) {
        // ConcurrentModificationException: expected
        // NoSuchElementException: (also legal given spec)
    }
    resetFull();
    final Iterator<E> iter0 = getCollection().iterator();
    getCollection().remove(getFullElements()[0]);
    assertThrows(ConcurrentModificationException.class, () -> iter0.next(), "next after remove should raise ConcurrentModification");
    resetFull();
    final Iterator<E> iter1 = getCollection().iterator();
    getCollection().removeIf(e -> false);
    assertThrows(ConcurrentModificationException.class, () -> iter1.next(), "next after removeIf should raise ConcurrentModification");
    resetFull();
    final Iterator<E> iter2 = getCollection().iterator();
    final List<E> sublist = Arrays.asList(getFullElements()).subList(2, 5);
    getCollection().removeAll(sublist);
    assertThrows(ConcurrentModificationException.class, () -> iter2.next(), "next after removeAll should raise ConcurrentModification");
    resetFull();
    final Iterator<E> iter3 = getCollection().iterator();
    final List<E> sublist3 = Arrays.asList(getFullElements()).subList(2, 5);
    getCollection().retainAll(sublist3);
    assertThrows(ConcurrentModificationException.class, () -> iter3.next(), "next after retainAll should raise ConcurrentModification");
}

