@Test
public void testWalkForwardAndBack() {
    final ArrayList<E> list = new ArrayList<>();
    final ListIterator<E> it = makeObject();
    while (it.hasNext()) {
        list.add(it.next());
    }
    // check state at end
    assertFalse(it.hasNext());
    assertTrue(it.hasPrevious());
    assertThrows(NoSuchElementException.class, () -> it.next(), "NoSuchElementException must be thrown from next at end of ListIterator");
    // loop back through comparing
    for (int i = list.size() - 1; i >= 0; i--) {
        assertEquals(i + 1, it.nextIndex());
        assertEquals(i, it.previousIndex());
        final Object obj = list.get(i);
        assertEquals(obj, it.previous());
    }
    // check state at start
    assertTrue(it.hasNext());
    assertFalse(it.hasPrevious());
    assertThrows(NoSuchElementException.class, () -> it.previous(), "NoSuchElementException must be thrown from previous at start of ListIterator");
}

