    MultiKey<Integer> mk;
    Integer[] keys = { THREE, FOUR, ONE, TWO };
    mk = new MultiKey<>(keys);
    assertArrayEquals(new Object[] { THREE, FOUR, ONE, TWO }, mk.getKeys());
    // no effect
    keys[3] = FIVE;
    assertArrayEquals(new Object[] { THREE, FOUR, ONE, TWO }, mk.getKeys());
