    final Map<Object, String> caseInsensitiveMap = new CaseInsensitiveMap<>(map);
    // ones collapsed
    assertEquals(4, caseInsensitiveMap.size());
    final Set<Object> keys = caseInsensitiveMap.keySet();
    assertTrue(keys.contains("one"));
